window.docContents[117].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Grammar-guided-interpolation":{"contents":"#eval Env.runIO do\n  let s ← Solver.new\n  s.setOption \"produce-interpolants\" \"true\"\n\n  let x ← s.declareConst Int \"x\"\n  let y ← s.declareConst Int \"y\"\n  let hyps := #[← smt! y = 6 * x + 3, ← smt! x ≥ 0]\n  for h in hyps do s.assert h\n  let goal ← smt! ¬ (y = 5) ∧ ¬ (y = 6)\n\n  if let some i ← s.getInterpolant goal then\n    println! \"free        : {i}\"\n\n  let g ← grammar! s where\n    start : Bool := atom | atom ∧ start\n    atom  : Bool := y % k = r\n    k     : Int  := 2 | 3 | 4 | 5\n    r     : Int  := 0 | 1 | 2\n\n  let some i ← s.getInterpolant goal g\n    | println! \"no interpolant\"\n  println! \"constrained : {i}\"\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.5. Grammar-guided interpolation","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Grammar-guided-interpolation"}});